#!/usr/bin/env -S node --experimental-transform-types
import { existsSync, readFileSync } from "node:fs";
import path from "node:path";
import { pathToFileURL } from "node:url";
import { BoundedProcessRunner, canonicalSha256 } from "../../bio-core/src/index.ts";
import { ClaudeWorkerClient } from "../../bio-runner/src/index.ts";
import { Journal } from "./journal.ts";
import { inspectHostAdapter } from "./host-adapter.ts";
import { investigate, type InvestigationConfig, type PipelineDependencies } from "./index.ts";

/** Host adapter is trusted executable configuration, never generated by a worker.
 * Keeping it mandatory avoids silently inventing boundary/audit evidence. */
export async function runCli(args: string[], injected?: PipelineDependencies): Promise<number> {
  if (![2, 4].includes(args.length) || args[0] !== "investigate" || !args[1] || (args.length === 4 && (args[2] !== "--host-adapter" || !args[3]))) throw new Error("Usage: cli.ts investigate <dir> --host-adapter <trusted-host.mjs>");
  const directory = path.resolve(args[1]);
  const config = JSON.parse(readFileSync(path.join(directory, "investigation.json"), "utf8")) as InvestigationConfig;
  let deps = injected;
  if (!deps) {
    if (!args[3]) throw new Error("--host-adapter is required outside the investigation directory");
    const identity = inspectHostAdapter(directory, args[3]);
    const journalFile = path.join(directory, "authority/pipeline.sqlite");
    if (existsSync(journalFile)) {
      const journal = new Journal(journalFile, config.id, Date.now);
      try {
        const old = journal.latest<{ hostAdapter?: unknown }>("configured")?.hostAdapter;
        if (!old || canonicalSha256(old) !== canonicalSha256(identity)) throw new Error("trusted host adapter changed or was not pinned");
      } finally { journal.close(); }
    }
    const module = await import(pathToFileURL(identity.path).href) as {
      createDependencies?: (defaults: { now: () => number; runner: BoundedProcessRunner; worker: ClaudeWorkerClient }) => PipelineDependencies | Promise<PipelineDependencies>;
    };
    if (typeof module.createDependencies !== "function") throw new Error("pipeline-host.mjs must export createDependencies; enforcement and auditing are required");
    const now = Date.now; // clock source only; all orchestration logic receives it by injection.
    const runner = new BoundedProcessRunner({ now });
    deps = { ...await module.createDependencies({ now, runner, worker: new ClaudeWorkerClient({ runner }) }), hostAdapter: identity };
    if (canonicalSha256(inspectHostAdapter(directory, identity.path)) !== canonicalSha256(identity)) throw new Error("trusted host adapter changed during import");
  }
  for (const key of ["now", "approve", "renderReport", "enforceWorkerBoundary", "auditWorker", "priorRecords"] as const) {
    if (typeof deps[key] !== "function") throw new Error(`missing trusted callback: ${key}`);
  }
  const result = await investigate(directory, config, deps);
  process.stdout.write(`${JSON.stringify(result)}\n`);
  return result.status === "completed" ? 0 : 1;
}
if (process.argv[1] && import.meta.url === pathToFileURL(path.resolve(process.argv[1])).href) {
  runCli(process.argv.slice(2)).then(code => { process.exitCode = code; }, error => {
    process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`); process.exitCode = 1;
  });
}
